domestic_main_or_first_bag_total.procedure:
def apply(inputs, premises):
    personal_used = False
    carry_used = False
    checked = []
    n = len(inputs["item_lengths"])
    for i in range(n):
        personal_ok = float(inputs["item_lengths"][i]) <= float(premises["personal_item_limits"][0]) and float(inputs["item_widths"][i]) <= float(premises["personal_item_limits"][1]) and float(inputs["item_heights"][i]) <= float(premises["personal_item_limits"][2])
        carry_ok = float(inputs["item_lengths"][i]) <= float(premises["carry_on_limits"][0]) and float(inputs["item_widths"][i]) <= float(premises["carry_on_limits"][1]) and float(inputs["item_heights"][i]) <= float(premises["carry_on_limits"][2])
        if personal_ok and not personal_used:
            personal_used = True
        elif carry_ok and not carry_used:
            carry_used = True
        else:
            checked = checked + [i]
    premium_cabin = inputs["cabin_class"] == "Premium Economy" or inputs["cabin_class"] == "Business" or inputs["cabin_class"] == "First"
    if inputs["route_fee_region"] == "domestic_us":
        if premium_cabin:
            base_schedule = premises["domestic_premium_base_schedule"]
        else:
            base_schedule = premises["domestic_economy_base_schedule"]
        overweight_schedule = premises["common_overweight_fees"]
        large_oversize_fee = int(premises["domestic_large_oversize_fee"])
    elif inputs["route_fee_region"] == "south_america_other":
        if premium_cabin:
            base_schedule = premises["south_america_premium_base_schedule"]
        else:
            base_schedule = premises["south_america_economy_base_schedule"]
        overweight_schedule = premises["common_overweight_fees"]
        large_oversize_fee = int(premises["south_america_large_oversize_fee"])
    else:
        if premium_cabin:
            base_schedule = premises["east_asia_premium_base_schedule"]
        else:
            base_schedule = premises["east_asia_economy_base_schedule"]
        overweight_schedule = premises["east_asia_overweight_fees"]
        large_oversize_fee = int(premises["east_asia_large_oversize_fee"])
    total = int(inputs["ticket_price"])
    for j in range(len(checked)):
        i = checked[j]
        if j < 4:
            base_fee = int(base_schedule[j])
        else:
            base_fee = int(base_schedule[3])
        standard_weight_limit = 50
        if (inputs["cabin_class"] == "First" or inputs["cabin_class"] == "Business") and base_fee == 0:
            standard_weight_limit = 70
        weight = float(inputs["item_weights"][i])
        overweight = 0
        if weight > standard_weight_limit:
            if weight <= 53:
                overweight = int(overweight_schedule[0])
            elif weight <= 70:
                overweight = int(overweight_schedule[1])
            else:
                overweight = int(overweight_schedule[2])
        size = float(inputs["item_lengths"][i]) + float(inputs["item_widths"][i]) + float(inputs["item_heights"][i])
        oversize = 0
        if size > 65:
            oversize = large_oversize_fee
        elif size > 62:
            oversize = int(premises["small_oversize_fee"])
        total = total + base_fee + max(overweight, oversize)
    return {"answer": total}
